-- ============================================================================
-- CƠ SỞ DỮ LIỆU DỰ ÁN: URBAN THREADS (urban_threads.sql / urban_threads.sqlite3)
-- Hệ thống Thương mại Điện tử Thời trang Streetwear Urban Threads VN
-- ============================================================================

-- ============================================================================
-- CÁC CÂU LỆNH TRUY VẤN SQL THỐNG KÊ (DÀNH CHO VẤN ĐÁP BÁO CÁO):
-- ============================================================================

-- 1. Truy vấn Tổng số Admin (Quản trị viên tối cao):
SELECT COUNT(*) AS tong_admin FROM accounts_user WHERE is_superuser = 1;

-- 2. Truy vấn Tổng số Nhân viên (Staff):
SELECT COUNT(*) AS tong_nhan_vien FROM accounts_user WHERE is_staff = 1 AND is_superuser = 0;

-- 3. Truy vấn Tổng số Khách hàng (Customers):
SELECT COUNT(*) AS tong_khach_hang FROM accounts_user WHERE is_staff = 0 AND is_superuser = 0;

-- 4. Truy vấn gộp thống kê cả 3 nhóm người dùng trên 1 bảng:
SELECT 
    COUNT(*) AS tong_tat_ca_tai_khoan,
    SUM(CASE WHEN is_superuser = 1 THEN 1 ELSE 0 END) AS tong_admin,
    SUM(CASE WHEN is_staff = 1 AND is_superuser = 0 THEN 1 ELSE 0 END) AS tong_nhan_vien,
    SUM(CASE WHEN is_staff = 0 AND is_superuser = 0 THEN 1 ELSE 0 END) AS tong_khach_hang
FROM accounts_user;

-- 5. Truy vấn danh sách chi tiết từng người dùng kèm phân loại Vai trò:
SELECT 
    id, email, first_name, last_name, phone,
    CASE 
        WHEN is_superuser = 1 THEN 'Admin Quản trị'
        WHEN is_staff = 1 THEN 'Nhân viên (Staff)'
        ELSE 'Khách hàng'
    END AS vai_tro
FROM accounts_user;

-- 6. Truy vấn Tổng số Sản phẩm và Tổng Tồn kho:
SELECT COUNT(*) AS tong_san_pham FROM products_product;
SELECT SUM(stock) AS tong_ton_kho FROM products_productvariant;

-- ============================================================================
-- CHI TIẾT CẤU TRÚC BẢNG (DDL) VÀ DỮ LIỆU THỰC NGHIỆM (DML):
-- ============================================================================

BEGIN TRANSACTION;
CREATE TABLE "accounts_address" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "full_name" varchar(100) NOT NULL, "phone" varchar(15) NOT NULL, "province" varchar(100) NOT NULL, "district" varchar(100) NOT NULL, "ward" varchar(100) NOT NULL, "street_address" varchar(255) NOT NULL, "is_default" bool NOT NULL, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "email" varchar(254) NOT NULL UNIQUE, "phone" varchar(15) NULL, "avatar" varchar(100) NULL, "date_of_birth" date NULL, "is_email_verified" bool NOT NULL);
CREATE TABLE "accounts_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "cart_cart" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "session_key" varchar(40) NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "coupon_code" varchar(50) NOT NULL, "user_id" bigint NULL UNIQUE REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "cart_cartitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "quantity" integer unsigned NOT NULL CHECK ("quantity" >= 0), "added_at" datetime NOT NULL, "cart_id" bigint NOT NULL REFERENCES "cart_cart" ("id") DEFERRABLE INITIALLY DEFERRED, "variant_id" bigint NOT NULL REFERENCES "products_productvariant" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "orders_order" ("id" char(32) NOT NULL PRIMARY KEY, "order_number" varchar(20) NOT NULL UNIQUE, "full_name" varchar(100) NOT NULL, "phone" varchar(15) NOT NULL, "email" varchar(254) NOT NULL, "province" varchar(100) NOT NULL, "district" varchar(100) NOT NULL, "ward" varchar(100) NOT NULL, "street_address" varchar(255) NOT NULL, "subtotal" decimal NOT NULL, "discount_amount" decimal NOT NULL, "shipping_fee" decimal NOT NULL, "total" decimal NOT NULL, "coupon_code" varchar(50) NOT NULL, "status" varchar(20) NOT NULL, "shipping_method" varchar(20) NOT NULL, "notes" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "shipped_at" datetime NULL, "delivered_at" datetime NULL, "user_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "payment_method" varchar(20) NOT NULL);
CREATE TABLE "orders_orderitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "product_name" varchar(200) NOT NULL, "color_name" varchar(50) NOT NULL, "size_name" varchar(20) NOT NULL, "unit_price" decimal NOT NULL, "quantity" integer unsigned NOT NULL CHECK ("quantity" >= 0), "product_image" varchar(500) NOT NULL, "order_id" char(32) NOT NULL REFERENCES "orders_order" ("id") DEFERRABLE INITIALLY DEFERRED, "variant_id" bigint NULL REFERENCES "products_productvariant" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "payments_payment" ("id" char(32) NOT NULL PRIMARY KEY, "amount" decimal NOT NULL, "status" varchar(20) NOT NULL, "receipt_image" varchar(100) NULL, "transaction_id" varchar(100) NOT NULL, "bank_name" varchar(50) NOT NULL, "notes" text NOT NULL, "created_at" datetime NOT NULL, "confirmed_at" datetime NULL, "order_id" char(32) NOT NULL UNIQUE REFERENCES "orders_order" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "products_category" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "slug" varchar(50) NOT NULL UNIQUE, "description" text NOT NULL, "image" varchar(100) NULL, "is_active" bool NOT NULL, "order" integer NOT NULL, "created_at" datetime NOT NULL, "parent_id" bigint NULL REFERENCES "products_category" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "products_color" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(50) NOT NULL, "hex_code" varchar(7) NOT NULL);
CREATE TABLE "products_product" ("id" char(32) NOT NULL PRIMARY KEY, "name" varchar(200) NOT NULL, "slug" varchar(250) NOT NULL UNIQUE, "description" text NOT NULL, "material" varchar(200) NOT NULL, "care_instructions" text NOT NULL, "gender" varchar(10) NOT NULL, "base_price" decimal NOT NULL, "sale_price" decimal NULL, "is_active" bool NOT NULL, "is_featured" bool NOT NULL, "is_new_arrival" bool NOT NULL, "is_best_seller" bool NOT NULL, "total_sold" integer NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "category_id" bigint NULL REFERENCES "products_category" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "products_productimage" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "image" varchar(100) NOT NULL, "alt_text" varchar(200) NOT NULL, "is_main" bool NOT NULL, "order" integer NOT NULL, "color_id" bigint NULL REFERENCES "products_color" ("id") DEFERRABLE INITIALLY DEFERRED, "product_id" char(32) NOT NULL REFERENCES "products_product" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "products_productvariant" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "stock" integer NOT NULL, "sku" varchar(100) NOT NULL UNIQUE, "extra_price" decimal NOT NULL, "color_id" bigint NULL REFERENCES "products_color" ("id") DEFERRABLE INITIALLY DEFERRED, "product_id" char(32) NOT NULL REFERENCES "products_product" ("id") DEFERRABLE INITIALLY DEFERRED, "size_id" bigint NULL REFERENCES "products_size" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "products_size" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(10) NOT NULL, "order" integer NOT NULL);
CREATE TABLE "promotions_banner" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "subtitle" varchar(300) NOT NULL, "image" varchar(100) NOT NULL, "image_mobile" varchar(100) NULL, "link" varchar(200) NOT NULL, "button_text" varchar(50) NOT NULL, "is_active" bool NOT NULL, "order" integer NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "promotions_coupon" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(50) NOT NULL UNIQUE, "description" varchar(200) NOT NULL, "discount_type" varchar(20) NOT NULL, "discount_value" decimal NOT NULL, "minimum_order" decimal NOT NULL, "max_uses" integer NOT NULL, "used_count" integer NOT NULL, "valid_from" datetime NOT NULL, "valid_to" datetime NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "reviews_review" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "rating" integer NOT NULL, "title" varchar(100) NOT NULL, "body" text NOT NULL, "is_approved" bool NOT NULL, "created_at" datetime NOT NULL, "product_id" char(32) NOT NULL REFERENCES "products_product" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
DELETE FROM "sqlite_sequence";
CREATE TABLE "wishlists_wishlist" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "user_id" bigint NOT NULL UNIQUE REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "wishlists_wishlist_products" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "wishlist_id" bigint NOT NULL REFERENCES "wishlists_wishlist" ("id") DEFERRABLE INITIALLY DEFERRED, "product_id" char(32) NOT NULL REFERENCES "products_product" ("id") DEFERRABLE INITIALLY DEFERRED);
