INSERT INTO "products_product" VALUES('bff9b90dfdb147c3a047549ae87fc325','Áo Thun Basic Oversize','ao-thun-basic-oversize','Áo thun oversize form rộng thoải mái, chất liệu cotton 100% mềm mịn. Phù hợp mặc hàng ngày hay dạo phố.','100% Cotton Combed 30s','','unisex',290000,NULL,1,1,1,1,0,'2026-10-02 08:59:01.447576','2026-10-02 11:28:58.021117',1);
INSERT INTO "products_product" VALUES('2f2861bab32c47febb3b9de833079ab4','Áo Thun Cổ Tròn Premium','ao-thun-co-tron-premium','Áo thun cổ tròn chất lượng cao, đường may chắc chắn. Form đứng vừa vặn phù hợp nhiều vóc dáng.','65% Cotton, 35% Polyester','','male',250000,199000,1,0,1,0,0,'2026-10-02 08:59:01.477030','2026-10-02 11:27:59.038330',1);
INSERT INTO "products_product" VALUES('96f4739c5a9741b59d17e26ae5962320','Hoodie Nặng Dây Kéo Urban','hoodie-nang-day-keo-urban','Hoodie dày dặn, chất nỉ bông bên trong siêu ấm. Thiết kế tối giản với logo Urban Threads thêu nhỏ ở ngực trái.','80% Cotton, 20% Polyester fleece','','unisex',590000,NULL,1,1,0,1,0,'2026-10-02 08:59:55.366594','2026-10-02 11:32:30.283755',2);
INSERT INTO "products_product" VALUES('751fd5130aa74f78b8f8a293cb9431ea','Sweater Cổ Tròn Vintage','sweater-co-tron-vintage','Sweater len cotton mềm mại, form boxy vintage. Cổ tay và gấu áo gân dệt co giãn tốt.','60% Cotton, 40% Acrylic','','unisex',490000,390000,1,0,1,0,0,'2026-10-02 08:59:55.942801','2026-10-02 11:24:53.468761',2);
INSERT INTO "products_product" VALUES('dc51193c6abd42509792e1e6159ac3c8','Áo Khoác Gió Lightweight','ao-khoac-gio-lightweight','Áo khoác gió siêu nhẹ, chống nước nhẹ. Dễ dàng gấp gọn trong túi khi không dùng. Phù hợp đi du lịch, ngoài trời.','Nylon Ripstop chống nước','','unisex',750000,NULL,1,1,0,0,0,'2026-10-02 08:59:56.269271','2026-10-02 11:10:35.352079',3);
INSERT INTO "products_product" VALUES('afaad773c3fd43a690c58dbe44156eaf','Quần Jeans Slim Fit Nam','quan-jeans-slim-fit-nam','Quần jeans nam ôm vừa, vải denim 9oz co giãn 4 chiều thoải mái. Phù hợp nhiều style từ casual đến smart casual.','Denim 9oz, 98% Cotton 2% Spandex','','male',550000,NULL,1,0,0,1,0,'2026-10-02 08:59:56.603282','2026-10-02 11:30:21.735302',4);
INSERT INTO "products_product" VALUES('93177e6a7c0a4c4fa3fc07549c867615','Quần Kaki Chino Công Sở','quan-kaki-chino-cong-so','Quần kaki chino thoáng mát, form slim straight lịch sự. Phù hợp đi làm, họp, sự kiện.','Cotton Kaki 230gsm','','male',480000,NULL,1,0,0,0,0,'2026-10-02 08:59:56.803329','2026-10-02 11:00:55.118617',4);
INSERT INTO "products_product" VALUES('5a05f6761e324126b31ed73537d0c89c','Áo Polo Cotton Piqué','ao-polo-cotton-pique','Áo polo vải piqué cotton thoáng mát, cổ bẻ gọn gàng. Phù hợp văn phòng và casual đơn giản.','100% Cotton Piqué 220gsm','','male',380000,299000,1,0,1,0,0,'2026-10-02 08:59:56.981753','2026-10-02 10:56:28.132123',5);
INSERT INTO "products_product" VALUES('39cc9d942733426e905feee4bf5f8e32','Áo Sơ Mi Oxford Button-Down','ao-so-mi-oxford-button-down','Áo sơ mi vải Oxford thông hơi tốt, không nhăn sau giặt. Form slim fit hiện đại.','Oxford Cotton 130gsm','','male',450000,NULL,1,1,0,0,0,'2026-10-02 08:59:57.319195','2026-10-02 10:50:32.390837',5);
INSERT INTO "products_product" VALUES('d43a06f8809a449aabe0e5c49deec5ad','Áo Thun Nữ Crop Ribbed','ao-thun-nu-crop-ribbed','Áo thun nữ dáng crop, vải gân thun co giãn 4 chiều ôm body. Phối với quần jeans hay chân váy đều đẹp.','95% Cotton 5% Elastane Ribbed','','female',200000,NULL,1,0,1,1,0,'2026-10-02 08:59:57.885461','2026-10-02 10:33:05.123408',1);
